import { useState } from 'react';
import { JxTagInput } from '@jinx-ui/react';

export interface ArticleTagPickerProps {
  value?: string[];
  defaultValue?: string[];
  onChange?: (tags: string[]) => void;
  label?: string;
  placeholder?: string;
  maxTags?: number;
}

function ArticleTagPicker({
  value,
  defaultValue = [],
  onChange,
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
  maxTags = 8,
}: ArticleTagPickerProps) {
  const [internalTags, setInternalTags] = useState<string[]>(defaultValue);
  const [notice, setNotice] = useState<string | null>(null);

  const tags = value ?? internalTags;

  const handleValueChange = (next: string[]) => {
    const seen = new Set<string>();
    const cleaned: string[] = [];
    let rejected: string | null = null;

    for (const raw of next) {
      const tag = raw.trim().replace(/\s+/g, ' ');
      if (!tag) continue;

      const key = tag.toLocaleLowerCase();
      if (seen.has(key)) {
        rejected = `Тег «${tag}» уже добавлен`;
        continue;
      }
      if (cleaned.length >= maxTags) {
        rejected = `Можно добавить не больше ${maxTags} тегов`;
        continue;
      }

      seen.add(key);
      cleaned.push(tag);
    }

    setNotice(rejected);

    const unchanged =
      cleaned.length === tags.length && cleaned.every((tag, i) => tag === tags[i]);
    if (unchanged) return;

    if (value === undefined) setInternalTags(cleaned);
    onChange?.(cleaned);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
      <span
        id="article-tag-picker-label"
        style={{ color: 'var(--jx-text)', fontSize: 'var(--jx-font-size-sm)' }}
      >
        {label}
      </span>

      <JxTagInput
        ariaLabel={label}
        placeholder={tags.length >= maxTags ? 'Достигнут лимит тегов' : placeholder}
        value={tags}
        onValueChange={handleValueChange}
      />

      <div
        role="status"
        aria-live="polite"
        style={{
          display: 'flex',
          flexWrap: 'wrap',
          alignItems: 'baseline',
          gap: '4px 12px',
          minHeight: '20px',
          fontSize: 'var(--jx-font-size-sm)',
        }}
      >
        {notice ? (
          <span style={{ color: 'var(--jx-danger)' }}>{notice}</span>
        ) : tags.length === 0 ? (
          <span style={{ color: 'var(--jx-text-2)' }}>
            Пока ни одного тега — введите слово и нажмите Enter, чтобы добавить метку.
          </span>
        ) : (
          <span style={{ color: 'var(--jx-text-2)' }}>
            Выбрано {tags.length} из {maxTags}: {tags.join(', ')}. Крестик на метке удаляет
            тег, Backspace в пустом поле — последний.
          </span>
        )}
      </div>
    </div>
  );
}

export default ArticleTagPicker;

